import Foundation
import Testing
@testable import GraineInApp

/**
 * EVERY ANSWER HERE WAS PRODUCED BY THE REACT NATIVE SDK'S OWN CODE.
 *
 * sdk/contract/rn-parity.json is generated by sdk/contract/generate-rn-parity.mjs,
 * which imports the RN SDK's built dist and runs its pure rules over a fixed
 * set of inputs. Every native SDK reads that one file and must reproduce each
 * answer exactly — a hand-written expected value would only be a second
 * opinion about what the first one says. A missing file FAILS; it never skips.
 */
@Suite struct RnParityTests {

    private func parity() throws -> [String: Any] {
        try ContractFile.load("rn-parity.json")
    }

    private func cases(_ name: String) throws -> [[String: Any]] {
        let list = try #require(try parity()[name] as? [[String: Any]], "section \(name) is missing from rn-parity.json")
        #expect(!list.isEmpty, "section \(name) is empty")
        return list
    }

    // MARK: - components

    @Test func normalisesAWidgetStyleExactlyAsReactNativeDoes() throws {
        for c in try cases("widgetStyle") {
            let got = styleMap(WidgetRules.normaliseStyle(c["input"]))
            #expect(Canon(c["output"]) == Canon(got), "input: \(Canon(c["input"]))")
        }
    }

    @Test func resolvesTheSameLook() throws {
        for c in try cases("widgetLook") {
            let look = WidgetRules.resolveLook(WidgetRules.normaliseStyle(c["style"]), kind: c["kind"] as? String)
            #expect(Canon(c["output"]) == Canon(lookMap(look)), "style: \(Canon(c["style"])) kind: \(Canon(c["kind"]))")
        }
    }

    @Test func putsEachKindOnTheSameSurface() throws {
        for c in try cases("widgetSurface") {
            #expect(WidgetRules.surface(kind: c["kind"] as? String).rawValue == c["output"] as? String, "kind: \(Canon(c["kind"]))")
        }
    }

    @Test func followsThePhonesGrammarTheSameWay() throws {
        for c in try cases("platform") {
            let got = WidgetRules.resolvePlatform(c["platform"] as? String, os: c["os"] as? String, manufacturer: c["manufacturer"] as? String)
            #expect(got == c["output"] as? String, "case: \(Canon(c))")
        }
        let want = try #require(try parity()["grammar"] as? [String: Any])
        #expect(Set(want.keys) == Set(WidgetRules.grammar.keys))
        for (name, expected) in want {
            let g = try #require(WidgetRules.grammar[name], "no grammar named \(name)")
            let mine: [String: Any] = [
                "radius": g.radius, "chipRadius": g.chipRadius, "buttonRadius": g.buttonRadius,
                "pillButtons": g.pillButtons, "separatorInset": g.separatorInset,
                "grabber": ["width": g.grabberWidth, "height": g.grabberHeight],
                "titleWeight": String(g.titleWeight), "padBoost": g.padBoost, "chipOutlined": g.chipOutlined,
            ]
            #expect(Canon(expected) == Canon(mine), "grammar: \(name)")
        }
    }

    @Test func allowlistsATapsActionTheSameWay() throws {
        for c in try cases("selectAction") {
            let input = c["input"]
            let got = WidgetRules.normaliseSelectAction(input)
            let want = try #require(c["output"] as? [String: Any])
            let argCount = ((input as? [String: Any])?["args"] as? [String: Any])?.count ?? 0
            if argCount > WidgetRules.selectArgMax {
                // Which ten survive depends on key order, and JSONSerialization does not keep it.
                // The count and the cut are the rule.
                let wantArgs = try #require(want["args"] as? [String: Any])
                #expect(got.args.count == wantArgs.count)
                #expect(got.args.values.allSatisfy { $0.count == WidgetRules.selectValueMax })
                #expect(got.action == want["action"] as? String)
                continue
            }
            var mine: [String: Any] = [:]
            if let v = got.action { mine["action"] = v }
            if let v = got.path { mine["path"] = v }
            if !got.args.isEmpty { mine["args"] = got.args }
            if let v = got.say { mine["say"] = v }
            #expect(Canon(want) == Canon(mine), "input: \(Canon(input))")
        }
    }

    @Test func runsTheSameActionForATap() throws {
        for c in try cases("selectCall") {
            let item = c["item"] as? [String: Any] ?? [:]
            let call = WidgetRules.selectCall(WidgetRules.normaliseSelectAction(c["onSelect"]), item: item)
            if Canon(c["output"]) == .null {
                #expect(call == nil, "case: \(Canon(c))")
                continue
            }
            let got = try #require(call, "case: \(Canon(c))")
            let mine: [String: Any] = ["name": got.name, "args": got.args]
            #expect(Canon(c["output"]) == Canon(mine), "case: \(Canon(c))")
        }
        for c in try cases("template") {
            let item = c["item"] as? [String: Any] ?? [:]
            let template = try #require(c["template"] as? String)
            #expect(WidgetRules.fillTemplate(template, item: item) == c["output"] as? String, "case: \(Canon(c))")
        }
    }

    @Test func namesSeveralChoicesInTheSameSentence() throws {
        for c in try cases("manySummary") {
            let titles = try #require(c["titles"] as? [String])
            let verb = try #require(c["verb"] as? String)
            #expect(WidgetRules.manySummary(titles, verb: verb) == c["output"] as? String, "case: \(Canon(c))")
        }
    }

    @Test func resolvesTheSamePictures() throws {
        for c in try cases("widgetImages") {
            let data = try #require(c["data"] as? [String: Any])
            let got = WidgetRules.resolveImages(data, baseUrl: c["baseUrl"] as? String)
            #expect(Canon(c["output"]) == Canon(got), "case: \(Canon(c))")
        }
    }

    // MARK: - the loader

    @Test func resolvesTheSameLoader() throws {
        for c in try cases("loaderStyle") {
            let n = Loaders.normalise(c["input"])
            var normalised: [String: Any] = [:]
            if let v = n.kind { normalised["kind"] = v }
            if let v = n.color { normalised["color"] = v }
            if let v = n.size { normalised["size"] = v }
            if let v = n.speed { normalised["speed"] = v }
            if let t = n.text {
                var text: [String: Any] = [:]
                for moment in Loaders.moments { if let w = t.forMoment(moment) { text[moment] = w } }
                normalised["text"] = text
            }
            if let v = n.skeleton { normalised["skeleton"] = v }
            #expect(Canon(c["normalised"]) == Canon(normalised), "normalise: \(Canon(c["input"]))")

            let r = Loaders.resolve(c["input"])
            let resolved: [String: Any] = [
                "kind": r.kind,
                "color": r.color ?? NSNull(),
                "px": r.px,
                "periodMs": r.periodMs,
                "skeleton": r.skeleton,
                "text": [
                    "connecting": r.text.connecting ?? "", "reconnecting": r.text.reconnecting ?? "",
                    "thinking": r.text.thinking ?? "", "component": r.text.component ?? "",
                ],
            ]
            #expect(Canon(c["resolved"]) == Canon(resolved), "resolve: \(Canon(c["input"]))")
        }
    }

    // MARK: - where the bar sits

    private func bounds(_ raw: Any?) throws -> PlacementMath.Bounds {
        let o = try #require(raw as? [String: Any])
        return PlacementMath.Bounds(
            windowHeight: try number(o["windowHeight"]),
            baseBottom: try number(o["baseBottom"]),
            barHeight: try number(o["barHeight"]),
            topMargin: o["topMargin"] == nil ? 48 : try number(o["topMargin"])
        )
    }

    @Test func placesTheBarWithTheSameArithmetic() throws {
        for c in try cases("clampOffset") {
            let got = PlacementMath.clampOffset(try number(c["offset"]), try bounds(c["bounds"]))
            #expect(Canon(c["output"]) == Canon(got), "case: \(Canon(c))")
        }
        for c in try cases("offsetDuringDrag") {
            let got = PlacementMath.offsetDuringDrag(start: try number(c["start"]), dy: try number(c["dy"]), try bounds(c["bounds"]))
            #expect(Canon(c["output"]) == Canon(got), "case: \(Canon(c))")
        }
        for c in try cases("isTap") {
            let got = PlacementMath.isTap(dx: try number(c["dx"]), dy: try number(c["dy"]))
            #expect(Canon(c["output"]) == Canon(got), "case: \(Canon(c))")
        }
        for c in try cases("liftFor") {
            let got = KeyboardMath.liftFor(keyboardHeight: try number(c["keyboard"]), windowShrink: try number(c["shrink"]))
            #expect(Canon(c["output"]) == Canon(got), "case: \(Canon(c))")
        }
    }

    // MARK: - appearance

    @Test func translatesTheDashboardsAppearanceTheSameWay() throws {
        for c in try cases("appearance") {
            let f = try #require(c["fallback"] as? [String: Any])
            let a = Appearance.resolve(
                c["appearance"] as? [String: Any],
                accent: try #require(f["accent"] as? String),
                heading: try #require(f["heading"] as? String),
                radius: f["radius"] == nil ? nil : try number(f["radius"]),
                maxRadius: f["maxRadius"] == nil ? nil : try number(f["maxRadius"]),
                origin: f["origin"] as? String
            )
            let mine: [String: Any] = [
                "accent": a.accent, "heading": a.heading, "logoUrl": a.logoUrl ?? NSNull(),
                "logoPlate": a.logoPlate.rawValue, "radius": a.radius,
            ]
            #expect(Canon(c["output"]) == Canon(mine), "case: \(Canon(c))")
        }
        // The plate is in the parity file, white, the accent and junk alike — not only defaulted.
        let plates = try cases("appearance").compactMap { ($0["output"] as? [String: Any])?["logoPlate"] as? String }
        #expect(plates.contains("white") && plates.contains("accent"), "rn-parity.json carries no white plate")
        for c in try cases("palette") {
            let p = Appearance.palette(c["appearance"] as? [String: Any], deviceDark: c["scheme"] as? String == "dark", accent: c["accent"] as? String)
            let mine: [String: Any] = [
                "surface": p.surface, "border": p.border, "text": p.text, "muted": p.muted, "onAccent": p.onAccent, "mode": p.mode,
            ]
            #expect(Canon(c["output"]) == Canon(mine), "case: \(Canon(c))")
        }
    }

    // MARK: - friction

    private func screenOf(_ raw: Any?) throws -> GraineScreen? {
        guard let o = raw as? [String: Any] else { return nil }
        let fields = try (o["fields"] as? [[String: Any]] ?? []).map { f -> GraineField in
            GraineField(
                name: try #require(f["name"] as? String),
                label: f["label"] as? String,
                value: f["value"] as? String,
                status: (f["status"] as? String).flatMap { GraineField.Status(rawValue: $0) },
                error: f["error"] as? String,
                isOptional: f["optional"] as? Bool ?? false
            )
        }
        return GraineScreen(screen: try #require(o["screen"] as? String), title: o["title"] as? String, fields: fields)
    }

    @Test func noticesAStalledCustomerAtTheSameMomentWithTheSameWords() throws {
        for script in try cases("frictionIdle") {
            let layers = try #require(script["config"] as? [[String: Any]])
            // The React Native rule itself: no outstanding-field gate, no call gate.
            let rules = Friction.resolve(layers.map { Optional($0) } + [["requireOutstandingField": false]])
            let detector = FrictionDetector(rules: rules, gateOnCall: false)
            let ops = try #require(script["ops"] as? [[Any]])
            let want = try #require(script["output"] as? [Any])
            #expect(ops.count == want.count)
            for (i, op) in ops.enumerated() {
                let name = try #require(op.first as? String)
                var got: Any? = nil
                switch name {
                case "screen":
                    detector.onScreen(try screenOf(op[1]), now: try number(op[2]))
                case "interaction":
                    detector.onInteraction(now: try number(op[1]))
                case "dueIn":
                    got = detector.idleDueIn(now: try number(op[1]))
                case "idle":
                    if let s = detector.onIdle(now: try number(op[1])) {
                        got = [
                            "name": s.name, "screen": s.screen, "detail": s.detail, "data": s.data,
                            "cooldown_seconds": s.cooldownSeconds, "max_per_session": s.maxPerSession,
                        ] as [String: Any]
                    }
                default:
                    Issue.record("unknown op \(name)")
                }
                #expect(Canon(want[i]) == Canon(got), "script \(Canon(script["config"])) op #\(i) \(Canon(op))")
            }
        }
    }

    // MARK: - helpers

    private func number(_ value: Any?) throws -> Double {
        let n = JSON.unwrap(value).flatMap { JSON.number($0) }
        return try #require(n, "not a number: \(String(describing: value))").doubleValue
    }

    private func styleMap(_ s: WidgetStyle) -> [String: Any] {
        var m: [String: Any] = [:]
        if let v = s.preset { m["preset"] = v.rawValue }
        if let v = s.imageSize { m["imageSize"] = v.rawValue }
        if let v = s.density { m["density"] = v.rawValue }
        if let v = s.button { m["button"] = v.rawValue }
        if let v = s.facts { m["facts"] = v }
        if let v = s.columns { m["columns"] = v }
        if let v = s.surface { m["surface"] = v.rawValue }
        if let v = s.radius { m["radius"] = v }
        if let v = s.accent { m["accent"] = v }
        if let v = s.platform { m["platform"] = v.rawValue }
        if let v = s.select { m["select"] = v.rawValue }
        if let v = s.maxSelect { m["maxSelect"] = v }
        return m
    }

    private func lookMap(_ l: WidgetLook) -> [String: Any] {
        var m: [String: Any] = [
            "preset": l.preset.rawValue, "imageSize": l.imageSize.rawValue, "density": l.density.rawValue,
            "button": l.button.rawValue, "facts": l.facts, "columns": l.columns, "surface": l.surface.rawValue,
            "platform": l.platform.rawValue, "select": l.select.rawValue, "maxSelect": l.maxSelect,
        ]
        if let v = l.radius { m["radius"] = v }
        if let v = l.accent { m["accent"] = v }
        return m
    }
}

/// JSON and Swift values in one comparable shape: numbers as doubles, objects by key, JSON null and nil alike.
indirect enum Canon: Equatable, CustomStringConvertible {
    case null
    case bool(Bool)
    case number(Double)
    case string(String)
    case array([Canon])
    case object([String: Canon])

    init(_ value: Any?) {
        guard let v = JSON.unwrap(value), !(v is NSNull) else { self = .null; return }
        if let b = JSON.bool(v) { self = .bool(b); return }
        if let n = JSON.number(v) { self = .number(n.doubleValue); return }
        if let s = v as? String { self = .string(s); return }
        if let a = v as? [Any] { self = .array(a.map { Canon($0) }); return }
        if let o = v as? [String: Any] { self = .object(o.mapValues { Canon($0) }); return }
        self = .string(String(describing: v))
    }

    var description: String {
        switch self {
        case .null: return "null"
        case .bool(let b): return b ? "true" : "false"
        case .number(let d): return JSON.jsNumberText(d)
        case .string(let s): return "\"\(s)\""
        case .array(let a): return "[" + a.map { $0.description }.joined(separator: ",") + "]"
        case .object(let o): return "{" + o.keys.sorted().map { "\"\($0)\":\(o[$0]!.description)" }.joined(separator: ",") + "}"
        }
    }
}
